13→// readCheckpointMetadataFull is the original ReadCheckpointMetadata implementation
14→// preserved for test code that needs the full deserialization behavior (loading
15→// every field from both the root CheckpointSummary and per-session CommittedMetadata).
16→//
17→// Production code uses ReadCheckpointMetadata which streams via json.Decoder
18→// and uses minimal structs to avoid allocating large unused fields
19→// (Summary, InitialAttribution, TokenUsage, etc.).
20→//
21→//nolint:unused // Test helper preserved for tests that need full deserialization
22→func readCheckpointMetadataFull(tree *object.Tree, checkpointPath string) (*CheckpointInfo, error) {
23→	metadataPath := checkpointPath + "/metadata.json"
24→	file, err := tree.File(metadataPath)
25→	if err != nil {
26→		return nil, fmt.Errorf("failed to find metadata at %s: %w", metadataPath, err)
27→	}
28→
29→	content, err := file.Contents()
30→	if err != nil {
31→		return nil, fmt.Errorf("failed to read metadata: %w", err)
32→	}
33→
34→	// Try to parse as CheckpointSummary first (new format)
35→	var summary checkpoint.CheckpointSummary
36→	if err := json.Unmarshal([]byte(content), &summary); err == nil {
37→		// If we have sessions array, this is the new format
38→		if len(summary.Sessions) > 0 {
39→			info := &CheckpointInfo{
40→				CheckpointID:     summary.CheckpointID,
41→				CheckpointsCount: summary.CheckpointsCount,
42→				FilesTouched:     summary.FilesTouched,
43→				SessionCount:     len(summary.Sessions),
44→			}
45→
46→			// Read all sessions' metadata to populate SessionIDs and get other fields from first session
47→			var sessionIDs []string
48→			for i, sessionPaths := range summary.Sessions {
49→				if sessionPaths.Metadata != "" {
50→					// SessionFilePaths now contains absolute paths with leading "/"
51→					// Strip the leading "/" for tree.File() which expects paths without leading slash
52→					sessionMetadataPath := strings.TrimPrefix(sessionPaths.Metadata, "/")
53→					if sessionFile, err := tree.File(sessionMetadataPath); err == nil {
54→						if sessionContent, err := sessionFile.Contents(); err == nil {
55→							var sessionMetadata checkpoint.CommittedMetadata
56→							if json.Unmarshal([]byte(sessionContent), &sessionMetadata) == nil {
57→								sessionIDs = append(sessionIDs, sessionMetadata.SessionID)
58→								// Use first session for Agent, SessionID, CreatedAt, IsTask, ToolUseID
59→								if i == 0 {
60→									info.Agent = sessionMetadata.Agent
61→									info.SessionID = sessionMetadata.SessionID
62→									info.CreatedAt = sessionMetadata.CreatedAt
63→									info.IsTask = sessionMetadata.IsTask
64→									info.ToolUseID = sessionMetadata.ToolUseID
65→								}
66→							}
67→						}
68→					}
69→				}
70→			}
71→			info.SessionIDs = sessionIDs
72→
73→			return info, nil
74→		}
75→	}
76→
77→	// Fall back to parsing as CheckpointInfo (old format or direct info)
78→	var metadata CheckpointInfo
79→	if err := json.Unmarshal([]byte(content), &metadata); err != nil {
80→		return nil, fmt.Errorf("failed to parse metadata: %w", err)
81→	}
82→
83→	return &metadata, nil
84→}
