459→// ReadCheckpointMetadata reads metadata.json from a checkpoint path on entire/checkpoints/v1.
460→// With the new format, root metadata.json is a CheckpointSummary with Agents array.
461→// This function reads the summary and extracts relevant fields into CheckpointInfo,
462→// also reading session-level metadata for IsTask/ToolUseID fields.
463→//
464→// Uses streaming json.Decoder and minimal structs to avoid loading large nested
465→// objects (Summary, InitialAttribution, TokenUsage) into memory.
466→func ReadCheckpointMetadata(tree checkpoint.FileReader, checkpointPath string) (*CheckpointInfo, error) {
467→	metadataPath := checkpointPath + "/metadata.json"
468→	file, err := tree.File(metadataPath)
469→	if err != nil {
470→		return nil, fmt.Errorf("failed to find metadata at %s: %w", metadataPath, err)
471→	}
472→
473→	reader, err := file.Reader()
474→	if err != nil {
475→		return nil, fmt.Errorf("failed to read metadata: %w", err)
476→	}
477→	defer reader.Close()
478→
479→	// Try to parse as CheckpointSummary first (new format) using lite struct
480→	var summary checkpointSummaryLite
481→	if decodeErr := json.NewDecoder(reader).Decode(&summary); decodeErr == nil {
482→		// If we have sessions array, this is the new format
483→		if len(summary.Sessions) > 0 {
484→			info := &CheckpointInfo{
485→				CheckpointID:     summary.CheckpointID,
486→				CheckpointsCount: summary.CheckpointsCount,
487→				FilesTouched:     summary.FilesTouched,
488→				SessionCount:     len(summary.Sessions),
489→			}
490→
491→			// Read all sessions' metadata to populate SessionIDs and get other fields from first session
492→			var sessionIDs []string
493→			for i, sessionPaths := range summary.Sessions {
494→				if sessionPaths.Metadata == "" {
495→					logging.Debug(context.Background(), "ReadCheckpointMetadata: session has empty metadata path",
496→						slog.Int("session_index", i),
497→						slog.String("checkpoint_path", checkpointPath),
498→					)
499→					continue
500→				}
501→				// SessionFilePaths contains absolute paths with leading "/"
502→				// Strip the leading "/" for tree.File() which expects paths without leading slash
503→				sessionMetadataPath := strings.TrimPrefix(sessionPaths.Metadata, "/")
504→				sessionMeta, sErr := decodeSessionMetadataLite(tree, sessionMetadataPath)
505→				if sErr != nil {
506→					logging.Debug(context.Background(), "ReadCheckpointMetadata: session metadata decode failed",
507→						slog.Int("session_index", i),
508→						slog.String("metadata_path", sessionMetadataPath),
509→						slog.String("error", sErr.Error()),
510→					)
511→					continue
512→				}
513→				sessionIDs = append(sessionIDs, sessionMeta.SessionID)
514→				// Use first session for Agent, SessionID, CreatedAt, IsTask, ToolUseID
515→				if i == 0 {
516→					info.Agent = sessionMeta.Agent
517→					info.SessionID = sessionMeta.SessionID
518→					info.CreatedAt = sessionMeta.CreatedAt
519→					info.IsTask = sessionMeta.IsTask
520→					info.ToolUseID = sessionMeta.ToolUseID
521→				}
522→			}
523→			info.SessionIDs = sessionIDs
524→
525→			return info, nil
526→		}
527→	}
528→
529→	// Fall back to parsing as CheckpointInfo (old format or direct info).
530→	// Re-read the file since the decoder consumed the reader.
531→	fallbackReader, err := file.Reader()
532→	if err != nil {
533→		return nil, fmt.Errorf("failed to re-read metadata: %w", err)
534→	}
535→	defer fallbackReader.Close()
536→
537→	var metadata CheckpointInfo
538→	if err := json.NewDecoder(fallbackReader).Decode(&metadata); err != nil {
539→		return nil, fmt.Errorf("failed to parse metadata: %w", err)
540→	}
541→
542→	return &metadata, nil
